content.text:
        if (stack.empty()) {
            hop = -1;
            len = -1;
        } else {
            const Prefix& w = pf[stack.back()];
            hop = static_cast<int64_t>(w.hop);
            len = static_cast<int32_t>(w.len);
        }
        if (first_group && key == 0) {
            rows[0] = Row{0, hop, len};  // never emit a second row at key 0
        } else if (hop != cur_hop || len != cur_len) {
            rows.push_back(Row{key, hop, len});
        }
        cur_hop = hop;
        cur_len = len;
        first_group = false;
    }
    if (rows.size() > kMaxImageRows) fail("compiled image exceeds 400001 rows");
    return rows;
}

void serialize(const std::vector<Row>& rows, std::string& out) {
    out.clear();
    out.reserve(24 + rows.size() * 31);
    out += "PLANB64 1\n";
    append_dec(out, rows.size());
    out.push_back('\n');
    for (size_t i = 0; i < rows.size(); ++i) {
        append_hex16(out, rows[i].start);
        out.push_back(' ');
        append_int(out, rows[i].hop);
        out.push_back(' ');
        append_int(out, rows[i].len);
        out.push_back('\n');
    }
}

// Publishes the image only once it is complete: a failed build never touches
// an existing destination and never creates a new one.
void publish(const char* dest, const std::string& data) {
    std::string tmpl(dest);
    if (tmpl.size() > 3800) fail("image path too long");
    tmpl += ".tmpXXXXXX";
    std::vector<char> path(tmpl.begin(), tmpl.end());
    path.push_back('\0');
    int fd = ::mkstemp(path.data());
    if (fd < 0)
        fail("cannot create temporary image next to " + quote(dest) + ": " +
             std::string(std::strerror(errno)));
    bool ok = true;
    const char* p = data.data();
    size_t n = data.size();
    while (n != 0) {
        ssize_t r = ::write(fd, p, n);
        if (r < 0) {
            if (errno == EINTR) continue;
            ok = false;
            break;
        }
        p += r;
        n -= static_cast<size_t>(r);
    }
    if (ok && ::fchmod(fd, 0644) != 0) ok = false;
    if (::close(fd) != 0) ok = false;
    if (!ok || ::rename(path.data(), dest) != 0) {
        ::unlink(path.data());
        fail("cannot write image " + quote(dest) + ": " + std::string(std::strerror(errno)));
    }
}

void cmd_build(const char* fib, const char* image) {
    std::vector<Prefix> pf;
    parse_fib(fib, pf);
    const std::vector<Row> rows = compile(pf);
    std::string data;
    serialize(rows, data);
    publish(image, data);
}

// ---------------------------------------------------------------------------
// Image reading.  The image is a standalone interval function; only the
// structural rules of the format are enforced.
// ---------------------------------------------------------------------------
int64_t parse_image_number(const char* p, size_t n, uint64_t limit) {
    if (n == 2 && p[0] == '-' && p[1] == '1') return -1;
    uint64_t v = 0;
    if (!parse_canon_dec(p, n, limit, v))
        fail("image: noncanonical or out-of-range numeric field");
    return static_cast<int64_t>(v);
}

void parse_image_row(const std::string& line, Row& row) {
    const size_t s1 = line.find(' ');
    if (s1 == std::string::npos) fail("image: row must have three fields");
    const size_t s2 = line.find(' ', s1 + 1);
    if (s2 == std::string::npos) fail("image: row must have three fields");
    if (line.find(' ', s2 + 1) != std::string::npos) fail("image: row must have three fields");
    if (s1 == 0 || s2 == s1 + 1 || s2 + 1 >= line.size())
        fail("image: rows use exactly one space between fields");

    uint64_t start = 0;
    if (!parse_hex16(line.data(), s1, start))
        fail("image: start key must be 16 lowercase hexadecimal digits");
    const int64_t hop = parse_image_number(line.data() + s1 + 1, s2 - s1 - 1, kMaxNextHop);
    const int64_t len = parse_image_number(line.data() + s2 + 1, line.size() - s2 - 1, kMaxPrefixLen);
    if ((hop < 0) != (len < 0)) fail("image: no-match fields must be paired");
    if (hop < 0 && (hop != -1 || len != -1)) fail("image: invalid no-match pair");
    row.start = start;
    row.hop = hop;
    row.len = static_cast<int32_t>(len);
}

void load_image(const char* path, std::vector<Row>& rows) {
    LineReader in(path, kMaxImageLine);
    in.open();
    std::string line;
    if (!in.next(line)) fail("image " + quote(path) + ": missing header");
    if (line != "PLANB64 1") fail("image " + quote(path) + ": bad header or version");
    if (!in.next(line)) fail("image " + quote(path) + ": missing row count");
    uint64_t count = 0;
    if (!parse_canon_dec(line.data(), line.size(), kMaxImageRows, count) || count == 0)
        fail("image " + quote(path) + ": row count must be 1..400001");
    rows.reserve(static_cast<size_t>(count));
    for (uint64_t i = 0; i < count; ++i) {
        if (!in.next(line)) fail("image " + quote(path) + ": fewer rows than announced");
        Row row{0, -1, -1};
        parse_image_row(line, row);
        if (i == 0) {
            if (row.start != 0) fail("image: first key must be 0000000000000000");
        } else {
            const Row& prev = rows.back();
            if (row.start <= prev.start) fail("image: keys must be strictly increasing");
            if (row.hop == prev.hop && row.len == prev.len)
                fail("image: adjacent rows must differ");
        }
        rows.push_back(row);
    }
    std::string extra;
    if (in.next(extra)) fail("image " + quote(path) + ": more rows than announced");
    if (!in.terminated()) fail("image " + quote(path) + ": missing final newline");
}

// ---------------------------------------------------------------------------
// Trace parsing: one IPv6 address per nonblank line.
// ---------------------------------------------------------------------------
void parse_trace(const char* path, std::vector<uint64_t>& keys) {
    LineReader in(path, kMaxLine);
    in.open();
    std::string line;
    Span tok[2];
    char addr[320];
